from pathlib import Path
import json,hashlib,difflib,gzip,subprocess,html,collections
out=Path(__file__).resolve().parent;main=Path('/workspace/orm-main');base=Path('/workspace/orm-adapted');labels=['base','checked','typed-old']
read=lambda p:json.loads(p.read_text());load=lambda p:[json.loads(x) for x in p.read_text().splitlines() if x.strip()]
ins={l:read(out/(l+'-inspection.json')) for l in labels};streams={l:load(out/(l+'-census.jsonl')) for l in labels};api=read(out/'api-pins.json');manifest=read(out/'adapted-source-hashes.json')
assert subprocess.check_output(['git','-C',str(main),'rev-parse','HEAD'],text=True).strip()=='219dbb6e7e20ea99d3e5d4b61c0cb14102dc9205'
assert not subprocess.check_output(['git','-C',str(main),'status','--porcelain','--untracked-files=no'])
assert all(hashlib.sha256((base/p).read_bytes()).hexdigest()==s for p,s in manifest.items())
assert all(len(ins[l]['roots'])==79 and not ins[l]['diagnostics'] and not ins[l]['emission']['emitSkipped'] and not ins[l]['emission']['diagnostics'] for l in labels)
assert not read(out/'counterexample-check.json')['diagnostics']
for label,tree in [('checked',Path('/workspace/cbp-checked')),('typed-old',Path('/workspace/cbp-typed-old'))]:
 changes={p:hashlib.sha256((tree/p).read_bytes()).hexdigest() for p,sha in manifest.items() if hashlib.sha256((tree/p).read_bytes()).hexdigest()!=sha};assert changes==read(out/(label+'-source-changes.json'))
# Stable correspondence is file/name/ordinal within the overload set; source changes preclude same-input identity pairing.
def view(label):
 counts=collections.Counter();result={};prefix=ins[label]['tree']+'/'
 for row in streams[label][1:-1]:
  first={}
  for f in row['findings']:
   if f['phase'] in ('lowering','deferred'):first.setdefault(f['unit'],f)
  for u in row['units']:
   name=u['name'];file=row['file'].removeprefix(prefix);counts[(file,name)]+=1;k=(file,name,counts[(file,name)])
   result[k]=dict(unit=u,first=first.get(u['where']))
 return result
views={l:view(l) for l in labels};assert len(views['base'])==9 and all(views[l].keys()==views['base'].keys() for l in labels)
assert all(len(load(out/(l+'-unit-times.jsonl')))==9 for l in labels)
prior=read(out.parent/'overload-results-main/overload-findings.json');old=[e['finding'] for e in prior['result']['observations'] if e['function']=='createBuilderProgram'];now=[v['first'] for v in views['base'].values()];assert old==now
assert all(not streams[l][0]['checker_rejected'] and streams[l][0]['latent_mode']=='first-error' and len(streams[l][0]['sources'])==81 and not streams[l][-1]['findings'] for l in labels)
assert all(not streams[l][-1]['relation_overflow']['after_load'] and not streams[l][-1]['relation_overflow']['end'] for l in labels)
assert all(all(not f['phase']=='refusal_scan' for row in streams[l] for f in row.get('findings',[])) for l in labels)
comparisons={};emits={}
for l in labels[1:]:
 rows=[]
 for k,b in views['base'].items():
  h=views[l][k];f=h['first'];status='cleared' if f is None else ('unchanged' if f['reason']==b['first']['reason'] else 'moved')
  rows.append(dict(key=k,base=b,head=h,status=status))
 comparisons[l]=dict(units=rows,cleared=sum(r['status']=='cleared' for r in rows),moved=sum(r['status']=='moved' for r in rows),unchanged=sum(r['status']=='unchanged' for r in rows),new_stops_from_clean_units=0,new_panics=sum(r['head']['first'] is not None and r['head']['first']['kind']=='panic' for r in rows),overload_result_first_stops=sum(r['head']['first'] is not None and r['head']['first']['reason'].startswith('overload ') and ' result ' in r['head']['first']['reason'] for r in rows),raw_first_stop_sites=len({(r['head']['first']['where'],r['head']['first']['kind'],r['head']['first']['reason'],r['head']['first']['text']) for r in rows if r['head']['first']}))
 b=ins['base']['emission']['outputs'];h=ins[l]['emission']['outputs'];assert b.keys()==h.keys();changed=[p for p in b if b[p]!=h[p]];diff=''
 for p in b:
  for label,entries in [('base',b),(l,h)]:
   data=(Path('/workspace/cbp-emit-'+label)/p).read_bytes();assert hashlib.sha256(data).hexdigest()==entries[p]['sha256']
 for p in changed:
  diff+=''.join(difflib.unified_diff((Path('/workspace/cbp-emit-base')/p).read_text().splitlines(True),(Path('/workspace/cbp-emit-'+l)/p).read_text().splitlines(True),fromfile='base/'+p,tofile=l+'/'+p))
 (out/(l+'-emitted.patch')).write_text(diff);emits[l]=dict(byte_identical=not changed,files_compared=len(b),changed_files=changed)
 for label in ['base',l]:
  for p in changed:
   dest=out/'emitted'/(label+'-'+p.replace('/','_')+'.gz');dest.parent.mkdir(exist_ok=True)
   with dest.open('wb') as stream:
    with gzip.GzipFile(fileobj=stream,mode='wb',mtime=0) as z:z.write((Path('/workspace/cbp-emit-'+label)/p).read_bytes())
(out/'comparisons.json').write_text(json.dumps(comparisons,indent=2)+'\n');(out/'emitted-comparison.json').write_text(json.dumps(emits,indent=2)+'\n')
def esc(x):return html.escape(str(x).replace('\r\n','\n').replace('\r',''),quote=False).replace('|','\\|').replace('\n','<br>')
def table(h,rs):return '\n'.join(['| '+' | '.join(h)+' |','| '+' | '.join(['---']*len(h))+' |',*['| '+' | '.join(esc(v) for v in r)+' |' for r in rs]])+'\n'
def loc(w,label='base'):return w.removeprefix(ins[label]['tree']+'/')
b=ins['base'];runtime=read(out/'runtime-counterexamples.json');assert runtime['crossKind']['returnedSameObject'] and runtime['plainBase']['returnedSameObject'] and len(runtime['errors'])==2
lines=['# createBuilderProgram: report-only adaptation measurements','',f"Pinned main **`{b['main']}`**, stock TypeScript **6.0.3**, and the exact original adapted tree from `overload-results-main`. All **747** source/input hashes are reverified. Only this report directory is committed; both candidate trees are scratch copies.",'','## 1. Entire implementation, callers and return paths','','The complete original implementation (including every nested body) is retained in `createBuilderProgram.original.ts.txt`; its checker-derived signature is:','','```ts',b['implementation']['signature'],'```','','Its overloads are:']
for i,d in enumerate(b['overloads'],1):lines+=['',str(i)+'. `'+d['location']+'`','','```ts',d['text'],'```']
lines+=['','There are exactly **two returns from createBuilderProgram itself**. The remaining 25 returns belong to nested helpers/callbacks; every one is listed in the appendix and `base-inspection.json`.','',table(['Return','Checker type','Reachability and promise'],[[r['location'],r['type'],('Fast reuse, before either kind branch. Can reach either overload with exactly the supplied oldProgram object. No kind/capability validation.' if r['text']=='return oldProgram;' else 'Fresh creation: kind 0 installs getSemanticDiagnosticsOfNextAffectedFile; kind 1 installs that method plus emitNextAffectedFile and overrides emitBuildInfo. Each valid kind therefore constructs its promised shape; an invalid kind throws via notImplemented before this return.')] for r in b['returns'] if r['outer']]),'','The exact reuse condition is:','','```ts','let oldState = oldProgram && oldProgram.state;','if (oldState && newProgram === oldState.program && configFileParsingDiagnostics === newProgram.getConfigFileParsingDiagnostics()) {','    newProgram = undefined!;','    oldState = undefined;','    return oldProgram;','}','```','','The diagnostics test is **array object identity**, not equal contents. Clearing local newProgram/oldState does not replace or enrich oldProgram. A truthy oldState implies a present oldProgram at runtime; the inferred `| undefined` reflects the checker’s lack of correlation between those locals. There is no actual undefined-return path in this body. A plain createAbstractBuilder result has state undefined, so it does not by itself take this reuse path. The counterexample below retains real builder state while omitting the subtype-only method.','','### All checkout callers','','A full-checkout grep (including harness, services and tests) finds only the two compiler files. The AST inventory covers all **712 .ts files under src**, including harness/services; all six identifiers are three declarations, one import specifier and these two calls. No other references or aliases appear. `whole-checkout-grep.txt` and the checker reference inventory are retained.','',table(['Call site','Enclosing caller','Resolved overload','Promise'],[[c['location'],'createSemanticDiagnosticsBuilderProgram' if c['overload']==1 else 'createEmitAndSemanticDiagnosticsBuilderProgram',c['overload'],'SemanticDiagnosticsBuilderProgram' if c['overload']==1 else 'EmitAndSemanticDiagnosticsBuilderProgram'] for c in b['calls']]),'','Every caller’s selected declaration text and signature are retained in `base-inspection.json`. The first passes kind 0 and getBuilderCreationParameters(...); the second passes kind 1 and the same parameter-building helper. The public wrappers each have two narrow overloads and one implementation, accounting for six census units; the internal helper’s two overloads and implementation account for the other three.','','## 2. Is the promise true?','','**The internal overload contract is false for admitted internal calls, with an observable missing-method result. The two existing checkout callers preserve a stronger invariant and do not exhibit that counterexample.**','','Their invariant is: an old builder already provides the capabilities promised by the requested wrapper. The semantic wrapper’s old parameter is SemanticDiagnosticsBuilderProgram; the emit wrapper’s is EmitAndSemanticDiagnosticsBuilderProgram. An emit builder may also serve the semantic wrapper because the emit interface extends the semantic one, so “created by exactly the same kind” is stronger than necessary. getBuilderCreationParameters preserves the old object’s identity but erases that subtype in its non-generic BuilderCreationParameters result. The internal overloads do not themselves encode or check the invariant.','','Two cast-free internal counterexamples type-check with zero diagnostics alongside all 79 roots (`counterexample.ts.txt`, `counterexample-check.json`):','','- Pass a real semantic old builder to kind 1 with the same Program and its diagnostics array. The overload promises EmitAndSemanticDiagnosticsBuilderProgram; the fast path returns that same semantic object, whose emitNextAffectedFile is undefined.','- Destructure only getSemanticDiagnosticsOfNextAffectedFile away from that real semantic old builder. The rest object is a structurally valid plain BuilderProgram retaining its real state. Pass it to kind 0 with the same Program/diagnostics. The overload promises SemanticDiagnosticsBuilderProgram, but returns the same plain object with the promised method absent.','','The runtime probe executes the **entire extracted adapted function**, not a reimplementation of its condition, using a real stock 6.0.3 builder/state. Both identity tests pass; both promised method calls throw TypeError. This establishes the helper’s contract hole without claiming an existing in-checkout call exercises it. The helper is internal, not a published typescript.d.ts function.','','## 3. Two measured adaptation shapes','','Two shapes were measured, within the requested maximum of three. Neither is ready to land: both remove the result-family stop only by moving every target unit to a different first stop. A split-function design was not measured, because the old-input invariant and honest result boundary can be tested with smaller, separately reviewable edits.','','### Checked: honest wide internal results, guarded public narrowing','','Both kind-specific internal overload results become `BuilderProgram | undefined`, exactly matching the inferred implementation result. Each public wrapper captures that result, tests presence of its required method(s) and `typeof ... === "function"`, then returns the original object with its narrow static type. The check is executable; the final structural assertion remains in the source. This experiment does not claim that a presence/function test proves an arbitrary structural method signature, nor that Adamic has approved the assertion: its first stops occur earlier. Source patches for both files are retained.','','The 79 compiler roots have **zero stock diagnostics**. Exactly **one of 79 emitted JavaScript files differs**, builderPublic.js; builder.js is byte-identical. These are all exact emitted hunks:','','```diff',(out/'checked-emitted.patch').read_text().rstrip(),'```','','Runtime behavior is therefore not declared byte-preserving: the two wrappers gain property reads/checks and may throw on a malformed old object. The public overload signatures and builder interfaces remain unchanged.','','### Typed-old: preserve the old builder subtype through parameters','','`BuilderCreationParameters<T extends BuilderProgram = BuilderProgram>` stores `oldProgram: T | undefined`; getBuilderCreationParameters becomes generic over the old subtype. Its existing three old-program assertions become `as T`, preserving the existing positional dispatch assumption. The two internal kind overloads require BuilderCreationParameters<SemanticDiagnosticsBuilderProgram> and BuilderCreationParameters<EmitAndSemanticDiagnosticsBuilderProgram> respectively. The implementation remains broad. This makes the existing callers’ type-level capability correlation explicit, rather than using it as an unencoded global assumption.','','The 79 roots have **zero stock diagnostics**. All **79 emitted JavaScript files are byte-identical** to baseline; `typed-old-emitted.patch` is empty. The result proof still does not get approved: the mutable narrow oldProgram field now meets the broad implementation parameter first, and the census refuses that parameter boundary. No public overload or interface changes.','','### Summary and all nine units','','“Moved” below means the same declaration unit still has a first stop, with a different reason. “Cleared” means it has no first stop. The overload-result family itself disappears from all nine first stops in both shapes, but **no unit clears**. Since the adapted source changes, units correspond by source path, function name and overload-set ordinal, rather than claiming same-input source-hash identity pairing.','',table(['Shape','79-root diagnostics','JS identical','Unit cleared','Unit moved','New stop from previously clean unit','New panic','Result first stops'],[[l,0,emits[l]['byte_identical'],comparisons[l]['cleared'],comparisons[l]['moved'],0,comparisons[l]['new_panics'],comparisons[l]['overload_result_first_stops']] for l in labels[1:]]),'','Baseline first stop for every row: `overload 1 of createBuilderProgram result SemanticDiagnosticsBuilderProgram cannot be served by implementation result BuilderProgram | undefined`, at `src/compiler/builder.ts:1686:1`. These fresh nine baseline findings match the earlier inventory **exactly**, including full diagnostic text. The stock checker resolves overload 2 in the emit wrapper, but censusOverloads validates the whole overload set and stops at incompatible overload 1; the finding number is not the call-resolution index.','']
for l in labels[1:]:
 lines+=['### '+l+' unit outcomes','',table(['Unit / overload-set ordinal','Base unit','Candidate unit','Outcome','Candidate first stop','Exact reason'],[[r['key'][1]+' #'+str(r['key'][2]),loc(r['base']['unit']['where']),loc(r['head']['unit']['where'],l),r['status'],loc(r['head']['first']['where'],l) if r['head']['first'] else 'none',r['head']['first']['reason'] if r['head']['first'] else 'none'] for r in comparisons[l]['units']])]
lines+=['','The checked shape has three unique new first-stop sites (one predicate target and one property-presence site per wrapper). Typed-old has one unique new parameter-stop site. These are new reasons/sites in already-stopped units, not regressions from clean units. Coverage here is exactly these nine units; no whole-project regression claim is made.','','### Public API status, for both shapes','',table(['Name','6.0.3 typescript.d.ts','stage3/lane/sanctioned-api.json'],[[n,v['typescriptDts'],v['sanctionedApi']] for n,v in api['names'].items()]),'','The helper, BuilderProgramKind enum, BuilderCreationParameters and getBuilderCreationParameters are internal and absent from both files. The two narrower builder interfaces and their public factories are published. They are absent from the sanction table; that absence is not permission to change them. BuilderProgram occurs in other sanction-table contexts. Automated AST comparison confirms that all public factory overload texts and all three public builder interface texts are identical to baseline in both shapes. No sanctioned-API edit is proposed.','','## 4. Existing adaptation pins','','The retained searches cover all of stage3/adapt: `adaptation-grep.txt` has 2,994 matching lines for createBuilderProgram or builder.ts; `affected-owner-grep.txt` has 32 lines for the helper parameter type, parameter-building helper and public wrappers. Long evidence lines are preview-truncated at 500 characters with their exact file/line retained; the original checkout remains the authoritative full text.','','The directly relevant exact owner pins are in **99-correctness-axolotl-x/owners.json**: `createBuilderProgram.emitBuildInfo`, `createBuilderProgram.emitNextAffectedFileOrDtsErrors`, and `createBuilderProgram.getWriteFileCallback`. Its adapt.cjs checks both the owner hashes and exact text, plus the core maybeBind/import inventory. All three nested owner hashes remain equal to their pinned after hashes on baseline and both scratch shapes (nine checks in api-pins.json). Neither proposal edits those nested bodies. A split/rename of the outer helper would need an explicit owner-pin/ownership review.','','Other builder.ts adaptations are present: 32-indexed-reads-program, 76-truthful-casts, 99-correctness-axolotl-j and 99-correctness-axolotl-k, with diagnostic/serialization owners elsewhere in the file; 70-readonly-views also records builder diagnostic/state ownership evidence. The k exact pins are convertOrRepopulateDiagnosticMessageChain and convertOrRepopulateDiagnosticMessageChainArray, and j touches toReusableCompilerOptionValue / createBuilderProgramUsingIncrementalBuildInfo, not the factory signatures or parameter helper edited here. The affected-owner search finds no exact pin naming BuilderCreationParameters, getBuilderCreationParameters or either public wrapper declaration. This is a targeted pin audit, not a claim that rerunning the entire adaptation pipeline on the candidates is approved or tested.','','## Method, limitations and validation','','The original own-main entry-census overlay is reused. First-error mode does not honor the full-mode LATENT_ONLY_FILE selector; two initial full-project pilots were explicitly terminated (child -15, shell 143) and retained separately, with no partial results used. A scratch-only selector was then layered over the validated scan-selector overlay, selecting exactly the nine top-level declarations by file and function name. It preserves complete source resolution, registration, eligibility, program facts, normal first-error lowering and both no-output guards. No refusal is suppressed inside a unit. Repeated whole-project refusal scans are omitted; no refusal-scan census or delta is claimed. The selected baseline’s nine full findings exactly reproduce the previous census. All final runs complete with zero diagnostics, nine attempted units/timings, no panic, and no relation overflow/global finding.','','All checks use stock TypeScript 6.0.3. The 79 roots are every recursive .ts root under src/compiler, with main’s bundled Node declaration index supplied as ambient context. Checking uses the same strict settings as main’s loader. Full program JavaScript emission uses ES2024/ESNext, LF and no maps/declarations, disables noEmit/allowImportingTsExtensions for emission, and hashes all 79 outputs; exact changed bytes and hunks are retained. The complete checkout search includes harness/services/tests even though the requested diagnostic measurement covers the 79 compiler roots.','','The first typed-old scratch edit had a mechanical THost token error (one diagnostic); the corrected final source and hashes were rechecked and produce zero diagnostics. Superseded inspection files and the terminated pilot streams are clearly named; no preliminary diagnostics or partial census contributes to final counts. Every potentially long child is bounded by run.py to 1,740 seconds with at most ten seconds to kill. Wrappers report and propagate their own child status. All final measurements/checks exit zero. Go evidence is named .go.txt. Commands, scripts, exact patches, complete streams, timings and hashes are retained.','','## Appendix: every return in the complete original implementation','',table(['Owner','Location','Return statement','Checker type'],[[r['owner'],r['location'],r['text'],r['type']] for r in b['returns']]),'']
