validation=dict(main=b['main'],same_747_original_hashes=True,stock_79_roots_diagnostics={l:len(ins[l]['diagnostics']) for l in labels},all_checkout_direct_callers=2,all_returns_inventoried=27,counterexample_stock_diagnostics=0,observable_counterexamples=2,selected_baseline_matches_previous_nine_exactly=True,units_per_side={l:len(views[l]) for l in labels},candidate_unit_counts={l:{k:v for k,v in comparisons[l].items() if k!='units'} for l in labels[1:]},emission=emits,public_factory_overloads_and_builder_interfaces_unchanged=True,exact_nested_owner_pins_verified=9,all_final_child_exits_zero=True,all_final_children_below_30_minutes=True)
